1	import { useState, useEffect } from 'react';
2	import Icon from '../Icons.jsx';
3	import VaultPicker from '../VaultPicker.jsx';
4	import OutputBrowser from '../OutputBrowser.jsx';
5	import { SourcesPanel, StackedPanel } from '../SourcesPanel.jsx';
6	import { runStage, ConflictError } from '../api.js';
7	import { announceStart, announceDone, announceFail } from '../jobActivity.js';
8	import useJobStream from '../hooks/useJobStream.js';
9	
10	const PLATFORMS = ['yt-long', 'yt-short', 'podcast'];
11	
12	export default function OutlineTab() {
13	  const [topic, setTopic] = useState('');
14	  const [hookPath, setHookPath] = useState(null);
15	  const [length, setLength] = useState(8);
16	  const [platform, setPlatform] = useState('yt-long');
17	  const [jobId, setJobId] = useState(null);
18	  const [runState, setRunState] = useState('idle');
19	  const [jobResult, setJobResult] = useState(null);
20	  const [jobError, setJobError] = useState(null);
21	  const [conflictNotice, setConflictNotice] = useState(false);
22	
23	  const jobStream = useJobStream(jobId);
24	
25	  /* eslint-disable react-hooks/set-state-in-effect */
26	  useEffect(() => {
27	    if (jobStream.status === 'completed') {
28	      setRunState('done');
29	      setJobResult(jobStream.result);
30	      announceDone('distribution');
31	    } else if (jobStream.status === 'failed') {
32	      setRunState('idle');
33	      setJobError(jobStream.error);
34	      announceFail('distribution');
35	    }
36	  }, [jobStream.status, jobStream.result, jobStream.error]);
37	  /* eslint-enable react-hooks/set-state-in-effect */
38	
39	  const handleRun = async () => {
40	    if (!topic.trim()) return;
41	    setRunState('loading');
42	    setJobError(null);
43	    setJobResult(null);
44	    setConflictNotice(false);
45	    announceStart('distribution');
46	    try {
47	      const body = { topic: topic.trim(), hook_path: hookPath || '', length, platform };
48	      const { job_id } = await runStage('outline', body);
49	      setJobId(job_id);
50	    } catch (e) {
51	      if (e instanceof ConflictError) {
52	        setConflictNotice(true);
53	        announceFail('distribution');
54	      } else {
55	        setJobError(e.message);
56	        announceFail('distribution');
57	      }
58	      setRunState('idle');
59	    }
60	  };
61	
62	  return (
63	    <div className="stage-split">
64	      <section className="input-zone">
65	        <div>
66	          <label className="field-label" htmlFor="outline-topic">Video topic</label>
67	          <div className="prompt-area">
68	            <textarea
69	              id="outline-topic"
70	              className="prompt-textarea"
71	              placeholder="e.g. Why open-source design tools are suddenly worth watching"
72	              value={topic}
73	              onChange={(e) => setTopic(e.target.value)}
74	              rows={3}
75	            />
76	            <span className="char-count">{topic.length}</span>
77	          </div>
78	        </div>
79	
80	        <div>
81	          <label className="field-label">Hook file (optional)</label>
82	          <VaultPicker
83	            folder="05-Hooks"
84	            value={hookPath}
85	            onChange={setHookPath}
86	            placeholder="Select hook file…"
87	          />
88	        </div>
89	
90	        <div style={{ display: 'flex', gap: 12 }}>
91	          <div style={{ flex: 1 }}>
92	            <label className="field-label" htmlFor="outline-length">Sections</label>
93	            <input
94	              id="outline-length"
95	              type="number"
96	              className="url-input"
97	              min={4}
98	              max={16}
99	              value={length}
100	              onChange={(e) => setLength(Number(e.target.value))}
101	              style={{ width: '100%' }}
102	            />
103	          </div>
104	          <div style={{ flex: 2 }}>
105	            <label className="field-label" htmlFor="outline-platform">Platform</label>
106	            <select
107	              id="outline-platform"
108	              className="vault-picker"
109	              value={platform}
110	              onChange={(e) => setPlatform(e.target.value)}
111	            >
112	              {PLATFORMS.map((p) => <option key={p} value={p}>{p}</option>)}
113	            </select>
114	          </div>
115	        </div>
116	
117	        {conflictNotice && (
118	          <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>A job is already running — wait for it to finish.</p>
119	        )}
120	        {jobError && (
121	          <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>Error: {jobError}</p>
122	        )}
123	
124	        <button
125	          className={'run-btn' + (runState === 'loading' ? ' loading' : runState === 'done' ? ' done' : '')}
126	          onClick={handleRun}
127	          disabled={runState === 'loading' || !topic.trim()}
128	        >
129	          {runState === 'loading' ? (
130	            <><span className="spinner-icon" style={{ display: 'grid', placeItems: 'center', animation: 'spin 0.8s linear infinite' }}><Icon.Loader size={14} /></span>Running…</>
131	          ) : runState === 'done' ? (
132	            <><Icon.Check size={14} />Done — View Results</>
133	          ) : (
134	            <><Icon.Play size={13} />Run Outline</>
135	          )}
136	        </button>
137	      </section>
138	
139	      <StackedPanel
140	        back={<SourcesPanel stageId="outline" />}
141	        front={<section className="output-zone">
142	        {runState === 'idle' && !jobResult && (
143	          <div className="output-empty">
144	            <div className="output-empty-icon"><Icon.ListTree size={26} /></div>
145	            <div style={{ fontSize: 14, color: 'var(--text-secondary)' }}>Run Outline to see results here</div>
146	          </div>
147	        )}
148	        {runState === 'loading' && (
149	          <>
150	            <div className="output-meta"><span>Running Outline… · streaming</span></div>
151	            <div className="output-body">
152	              {jobStream.lines.length > 0 ? (
153	                <div style={{ fontFamily: 'monospace', fontSize: 12, lineHeight: 1.6 }}>
154	                  {jobStream.lines.map((line, i) => <div key={i}>{line}</div>)}
155	                </div>
156	              ) : (
157	                <>
158	                  <div className="skeleton skeleton-row long" />
159	                  <div className="skeleton skeleton-row medium" />
160	                  <div className="skeleton skeleton-block" />
161	                </>
162	              )}
163	            </div>
164	          </>
165	        )}
166	        {runState === 'done' && jobResult && (
167	          <>
168	            <div className="output-meta">
169	              <span>Saved to vault · 06-Outlines</span>
170	              <div className="output-meta-actions">
171	                <button className="btn-icon" title="Copy path" onClick={() => navigator.clipboard.writeText(jobResult.primary_path || '')}>
172	                  <Icon.Copy size={14} />
173	                </button>
174	              </div>
175	            </div>
176	            <OutputBrowser result={jobResult} />
177	          </>
178	        )}
179	      </section>}
180	      />
181	    </div>
182	  );
183	}
