file.content:
  font-size: 12px;
  font-family: var(--font-ui);
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease, transform 200ms cubic-bezier(0.2,0.7,0.2,1);
}
.viewer-back:hover {
  background: var(--bg-elevated);
  color: var(--text-primary);
  transform: translateX(-2px);
}
.viewer-path {
  flex: 1;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.viewer-path-name {
  color: var(--page-accent);
  font-weight: 500;
}
.viewer-meta-pill {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 4px 8px;
  border-radius: var(--r-pill);
  background: color-mix(in oklab, var(--page-accent) 14%, transparent);
  color: var(--page-accent);
  border: 1px solid color-mix(in oklab, var(--page-accent) 28%, var(--border));
  flex-shrink: 0;
}
.viewer-actions { display: flex; gap: 6px; }
.viewer-body {
  padding: 24px 28px;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}
.viewer-empty-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  margin: 0 0 18px;
  padding: 12px 14px;
  background: var(--bg-elevated);
  border-radius: var(--r-input);
  border: 1px solid var(--border);
}
.viewer-empty-meta-key { color: var(--text-secondary); letter-spacing: 0.06em; text-transform: uppercase; }
.viewer-empty-meta-val { color: var(--text-primary); }
.viewer-external {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: var(--r-button);
  background: color-mix(in oklab, var(--page-accent) 10%, transparent);
  border: 1px solid color-mix(in oklab, var(--page-accent) 32%, var(--border));
  color: var(--page-accent);
  font-family: var(--font-mono);
  font-size: 12px;
  cursor: pointer;
  transition: background 120ms ease;
}
.viewer-external:hover { background: color-mix(in oklab, var(--page-accent) 18%, transparent); }
.source-link-favicon {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border-radius: 5px;
  background: color-mix(in oklab, var(--page-accent) 16%, transparent);
  color: var(--page-accent);
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
}
.source-link-body { flex: 1; min-width: 0; }
.source-link-title {
  font-size: 13px;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-bottom: 2px;
}
.source-link-url {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.source-link-meta {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
  flex-shrink: 0;
}

/* ============================================================
   Brain banner (Dashboard hero strip)
   ============================================================ */
.brain-banner {
  position: relative;
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 24px;
  padding: 22px 26px;
  margin-bottom: 20px;
  border: 1px solid color-mix(in oklab, var(--brain) 30%, var(--border));
  border-radius: var(--r-card);
  background:
    radial-gradient(120% 180% at 0% 0%, color-mix(in oklab, var(--brain) 14%, transparent) 0%, transparent 55%),
    radial-gradient(80% 200% at 100% 100%, color-mix(in oklab, var(--brain) 10%, transparent) 0%, transparent 50%),
    var(--bg-surface);
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  font-family: var(--font-ui);
  transition:
    transform 280ms cubic-bezier(0.2, 0.7, 0.2, 1),
    border-color 220ms ease,
    box-shadow 280ms ease;
  box-shadow: 0 0 0 0 transparent;
}
.brain-banner:hover {
  transform: translateY(-2px);
  border-color: color-mix(in oklab, var(--brain) 55%, var(--border));
  box-shadow:
    0 16px 36px -18px rgba(0, 0, 0, 0.7),
    0 0 32px -10px color-mix(in oklab, var(--brain) 50%, transparent);
}

.brain-banner-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background:
    radial-gradient(circle at 30% 30%, color-mix(in oklab, var(--brain) 38%, transparent), transparent 70%),
    var(--bg-elevated);
  color: var(--brain);
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in oklab, var(--brain) 30%, var(--border));
  position: relative;
  z-index: 1;
  transition: transform 320ms cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 280ms ease;
  flex-shrink: 0;
}
.brain-banner:hover .brain-banner-icon {
  transform: rotate(-6deg) scale(1.04);
  box-shadow: 0 0 24px -4px color-mix(in oklab, var(--brain) 60%, transparent);
}
.brain-banner-icon svg {
  filter: drop-shadow(0 0 8px color-mix(in oklab, var(--brain) 50%, transparent));
  animation: brainPulse 3.6s ease-in-out infinite;
}
@keyframes brainPulse {
  0%, 100% { filter: drop-shadow(0 0 6px color-mix(in oklab, var(--brain) 40%, transparent)); }
  50%      { filter: drop-shadow(0 0 14px color-mix(in oklab, var(--brain) 80%, transparent)); }
}

.brain-banner-text {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.brain-banner-eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--brain);
}
.brain-banner-title {
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -0.015em;
  color: var(--text-primary);
  line-height: 1.1;
  transition: letter-spacing 240ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.brain-banner:hover .brain-banner-title { letter-spacing: 0em; }
.brain-banner-tagline {
  font-size: 14px;
  color: var(--text-secondary);
  font-style: italic;
  margin-top: 2px;
}

.brain-banner-stats {
  display: flex;
  align-items: stretch;
  gap: 0;
  position: relative;
  z-index: 1;
  padding-left: 24px;
  border-left: 1px solid var(--border);
}
.brain-banner-stat {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 0 18px;
  border-right: 1px dashed var(--border);
  min-width: 88px;
}
.brain-banner-stat:last-child { border-right: none; padding-right: 0; }
.brain-banner-stat:first-child { padding-left: 0; }
.brain-banner-stat-value {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 600;
  color: var(--brain);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.brain-banner-stat-label {
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: 4px;
  font-family: var(--font-mono);
}

.brain-banner-cta {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: var(--r-button);
  border: 1px solid color-mix(in oklab, var(--brain) 30%, var(--border));
  background: color-mix(in oklab, var(--brain) 10%, transparent);
  color: var(--brain);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transition:
    background 200ms ease,
    border-color 200ms ease,
    color 200ms ease,
    transform 240ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.brain-banner-cta svg {
  transition: transform 240ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.brain-banner:hover .brain-banner-cta {
  background: var(--brain);
  border-color: var(--brain);
  color: var(--bg-base);
}
.brain-banner:hover .brain-banner-cta svg { transform: translateX(4px); }

/* Decorative orbs */
.brain-banner-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
  pointer-events: none;
  z-index: 0;
  opacity: 0.55;
  transition: opacity 400ms ease, transform 600ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.brain-banner-orb-1 {
  width: 220px;
  height: 220px;
  background: color-mix(in oklab, var(--brain) 50%, transparent);
  top: -120px;
  left: -60px;
}
.brain-banner-orb-2 {
  width: 180px;
  height: 180px;
  background: color-mix(in oklab, var(--accent) 35%, transparent);
  bottom: -110px;
  right: 20%;
}
.brain-banner:hover .brain-banner-orb-1 { transform: translate(20px, 10px); opacity: 0.75; }
.brain-banner:hover .brain-banner-orb-2 { transform: translate(-30px, -10px); opacity: 0.75; }

/* Narrow viewport — collapse the stats column */
@media (max-width: 1100px) {
  .brain-banner { grid-template-columns: auto 1fr auto; }
  .brain-banner-stats { display: none; }
}

/* ============================================================
   Motion polish — make the page feel alive on hover
   ============================================================ */

/* Page entrance — content fades in when a view mounts.
   Opacity-only (no transform) so it doesn't create a containing block
   that would trap position:fixed drawers. */
.main-inner > [data-screen-label] {
  animation: viewIn 320ms ease-out both;
}
@keyframes viewIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* Page title — hover responds with letter-spacing + slight slide */
.page-title, .stage-title {
  transition:
    letter-spacing 240ms cubic-bezier(0.2, 0.7, 0.2, 1),
    color 200ms ease,
    transform 240ms cubic-bezier(0.2, 0.7, 0.2, 1);
  transform-origin: left center;
  cursor: default;
  display: inline-flex;
  will-change: letter-spacing, transform;
}
.page-title:hover {
  letter-spacing: 0.01em;
  transform: translateX(2px);
}
.stage-title:hover {
  letter-spacing: 0.005em;
  transform: translateX(2px);
}
.stage-title:hover svg {
  transform: rotate(-6deg) scale(1.05);
}
.stage-title svg {
  transition: transform 260ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* Card title row — animated underline that slides in on hover */
.dash-card-name {
  position: relative;
  display: inline-block;
  transition: color 200ms ease, letter-spacing 240ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.dash-card-name::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 1px;
  background: var(--stage-color);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 320ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.dash-card:hover .dash-card-name {
  color: var(--stage-color);
  letter-spacing: 0.14em; /* expand */
}
.dash-card:hover .dash-card-name::after {
  transform: scaleX(1);
}

/* Card stage icon — bloom on hover */
.dash-card-icon {
  transition:
    transform 280ms cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 280ms ease,
    background 200ms ease;
}
.dash-card:hover .dash-card-icon {
  transform: scale(1.08) rotate(-4deg);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--stage-color) 8%, transparent);
}

/* Stronger lift + glow on card */
.dash-card {
  transition:
    border-color 220ms ease,
    background 220ms ease,
    transform 280ms cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 280ms ease;
}
.dash-card:hover {
  transform: translateY(-3px);
  box-shadow:
    0 12px 32px -16px rgba(0, 0, 0, 0.6),
    0 0 0 1px var(--border-active),
    0 0 24px -8px color-mix(in oklab, var(--stage-color) 30%, transparent);
}

/* Open-arrow slides on hover */
.dash-card-open svg {
  transition: transform 260ms cubic-bezier(0.2, 0.7, 0.2, 1), color 200ms ease;
}
.dash-card:hover .dash-card-open svg {
  transform: translateX(4px);
  color: var(--stage-color);
}

/* Activity items — slide right + stage-tint on row hover */
.activity-item {
  transition:
    transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1),
    color 180ms ease;
  cursor: pointer;
  position: relative;
}
.activity-item:hover { transform: translateX(4px); }
.activity-item:hover .activity-text { color: var(--stage-color); }
.activity-text {
  transition: color 180ms ease;
}

/* Topic pills + badges */
.topic-pill, .source-badge, .status-chip {
  transition:
    transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1),
    background 180ms ease,
    color 180ms ease;
}
.activity-item:hover .topic-pill {
  transform: translateY(-1px);
}
.activity-item:hover .source-badge {
  background: color-mix(in oklab, var(--stage-color) 14%, transparent);
  color: var(--stage-color);
}
.relevance-bar-fill {
  transition: width 600ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* Buttons — primary + ghost + stage */
.btn, .btn-icon, .run-btn {
  transition:
    background 120ms ease,
    border-color 120ms ease,
    color 120ms ease,
    transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 180ms ease;
}
.btn-primary {
  position: relative;
  overflow: hidden;
}
.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px -8px color-mix(in oklab, var(--accent) 70%, transparent);
}
.btn-primary:active { transform: translateY(0); }
.btn-primary::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 30%, rgba(255,255,255,0.18) 50%, transparent 70%);
  transform: translateX(-120%);
  transition: transform 600ms ease;
}
.btn-primary:hover::after { transform: translateX(120%); }
.btn-primary svg { transition: transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.btn-primary:hover svg { transform: rotate(90deg); }

.btn-ghost:hover { transform: translateY(-1px); }
.btn-stage {
  position: relative;
  overflow: hidden;
}
.btn-stage:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px -10px color-mix(in oklab, var(--stage-color) 70%, transparent);
}
.btn-stage svg { transition: transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.btn-stage:hover svg { transform: translateX(2px); }
.btn-icon:hover { transform: scale(1.08); }
.back-btn {
  transition: background 120ms ease, color 120ms ease, transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.back-btn:hover { transform: translateX(-2px); }

/* Run button — pulse halo while loading, glow on hover */
.run-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 8px 22px -10px color-mix(in oklab, var(--stage-color) 70%, transparent);
}
.run-btn svg { transition: transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.run-btn:hover:not(:disabled) svg { transform: translateX(2px); }

/* Inputs — motion on focus + hover */
.prompt-textarea, .url-input-row, .drop-zone {
  transition:
    border-color 180ms ease,
    box-shadow 220ms ease,
    background 180ms ease,
    transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.prompt-textarea:hover {
  border-color: var(--border-active);
}
.prompt-textarea:focus {
  transform: translateY(-1px);
}
.url-input-row:hover {
  border-color: var(--border-active);
}
.url-input-row:focus-within {
  transform: translateY(-1px);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--stage-color) 18%, transparent);
}
.drop-zone:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px -12px rgba(0,0,0,0.6);
}
.drop-zone svg { transition: transform 280ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.drop-zone:hover svg { transform: translateY(-2px) scale(1.08); }

/* Format pills bounce on group hover */
.drop-zone .format-pill {
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1), background 180ms ease;
}
.drop-zone:hover .format-pill:nth-child(1) { transform: translateY(-2px); }
.drop-zone:hover .format-pill:nth-child(2) { transform: translateY(-2px); transition-delay: 40ms; }
.drop-zone:hover .format-pill:nth-child(3) { transform: translateY(-2px); transition-delay: 80ms; }
.drop-zone:hover .format-pill:nth-child(4) { transform: translateY(-2px); transition-delay: 120ms; }

/* Chips — pop on hover, remove button rotates */
.file-chip, .url-chip {
  transition: transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1), border-color 180ms ease;
}
.file-chip:hover, .url-chip:hover {
  transform: translateY(-1px);
  border-color: var(--stage-color);
}
.chip-close { transition: background 120ms ease, color 120ms ease, transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.chip-close:hover { transform: rotate(90deg); }

/* Sidebar nav items — slide indicator + icon shift */
.nav-item {
  transition:
    background 120ms ease,
    border-left-color 120ms ease,
    padding-left 220ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.nav-item .nav-icon {
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.app:not(.collapsed) .nav-item:hover {
  padding-left: 14px;
}
.app:not(.collapsed) .nav-item:hover .nav-icon {
  transform: scale(1.1);
}
.nav-item .nav-label {
  transition: letter-spacing 200ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.app:not(.collapsed) .nav-item:hover .nav-label {
  letter-spacing: 0.01em;
}
.nav-item.active .nav-icon {
  transform: scale(1.05);
}

/* Hook cards — lift + number pop on hover */
.hook-card {
  transition:
    border-color 180ms ease,
    transform 220ms cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 220ms ease;
}
.hook-card:hover {
  transform: translateX(3px);
  box-shadow: -3px 0 0 0 var(--stage-color);
  border-color: var(--border-active);
}
.hook-num {
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.hook-card:hover .hook-num { transform: scale(1.12); }

/* Analysis sections (Brain) — header lift, chevron + num pop */
.analysis-section-header {
  transition: background 140ms ease, padding-left 220ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.analysis-section-header:hover { padding-left: 24px; }
.analysis-section-num {
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.2, 1), color 180ms ease;
}
.analysis-section-header:hover .analysis-section-num {
  transform: translateX(-2px) scale(1.1);
}

/* Score cards — arc rotates subtly, value scales */
.score-card {
  transition: border-color 200ms ease, transform 240ms cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 240ms ease;
}
.score-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-active);
  box-shadow: 0 12px 32px -16px rgba(0,0,0,0.6);
}
.score-arc-fill {
  transition: stroke-dashoffset 800ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* Trigger chips — bounce-stagger on hover */
.trigger-chip {
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1), background 180ms ease;
}
.trigger-chip:hover {
  transform: translateY(-2px);
  background: color-mix(in oklab, var(--brain) 24%, transparent);
}

/* Distribution tab bar */
.dist-tab-bar {
  display: flex;
  gap: 4px;
  margin: 16px 0 0;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0;
}
.dist-tab {
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  padding: 8px 16px 10px;
  transition: color 140ms ease, border-color 140ms ease;
  margin-bottom: -1px;
}
.dist-tab:hover { color: var(--text-primary); }
.dist-tab.is-active {
  border-bottom-color: var(--stage-color, var(--accent));
  color: var(--text-primary);
}
.dist-tab-content {
  padding-top: 20px;
}

/* Reduce motion preference — be respectful */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

